export async function releaseDemoFixture(
  id: string,
): Promise<ReleasePollResponse | ReleaseSeriesResponse> {
  const entry = RELEASE_DEMO_FIXTURES.find((row) => row.id === id);
  if (!entry) throw new ReleaseResponseError();
  return entry.kind === "poll"
    ? parseReleasePollResponse(entry.rawJson, entry.request)
    : parseReleaseSeriesResponse(entry.rawJson, entry.request);
}
export async function demoCollectReleaseCadence(
  value: ReleasePollRequest,
): Promise<ReleasePollResponse> {
  const captured = snapshotReleasePollRequest(value);
  const entry = RELEASE_DEMO_FIXTURES.find(
    (row) =>
      row.kind === "poll" &&
      Object.entries(row.request).every(
        ([key, v]) => Reflect.get(captured, key) === v,
      ),
  );
  if (!entry)
    throw new ReleaseResponseError(
      "Choose one of the synthetic release examples.",
    );
  return parseReleasePollResponse(entry.rawJson, captured);
}
export async function demoReleaseSeries(
  value: ReleaseSeriesRequest,
): Promise<ReleaseSeriesResponse> {
  const captured = snapshotReleaseSeriesRequest(value);
  const candidates = [...RELEASE_DEMO_FIXTURES].sort(
    (a, b) => Number(b.id === "series-two") - Number(a.id === "series-two"),
  );
  const entry = candidates.find(
    (row) =>
      row.kind === "series" &&
      Object.entries(row.request).every(
        ([key, v]) => Reflect.get(captured, key) === v,
      ),
  );
  if (!entry)
    throw new ReleaseResponseError(
      "Choose one of the synthetic release examples.",
    );
  return parseReleaseSeriesResponse(entry.rawJson, captured);
}
